"""Build matching standalone border/overlay shaders from shared Diya artwork."""
from pathlib import Path

root = Path(__file__).resolve().parents[3]
material = Path(__file__).with_name('diya-material.glsl').read_text()
prefix = '''// SPDX-License-Identifier: MIT
// Copyright (c) 2026 Barrulus. Original Diwali artwork with Codex assistance.
// Perimeter geometry adapted from Barrulus's Fairy Lights / Ghostly Tear Border.
// Generated by packs/diwali/tools/generate_diya.py; edit packs/diwali/tools/diya-material.glsl for both halves.
'''
border = prefix + '#define DIYA_RADII umbriel_border_radius\n' + material + '''
vec4 border(vec2 uv) {
    vec2 size=umbriel_border_hole.zw*umbriel_size;
    if(min(size.x,size.y)<=0.0) return vec4(0.0);
    float d=umbriel_border_distance(uv);
    if(d<0.0 || d>=REACH) return vec4(0.0);
    vec2 point=(uv-umbriel_border_hole.xy)*umbriel_size;
    return diya_material(point,size,d);
}
'''
overlay = prefix + '#define DIYA_RADII umbriel_corner_radius\n' + material + '''
float diya_distance(vec2 point) {
    vec2 halfSize=umbriel_size*0.5;
    vec2 p=point-halfSize;
    float r=p.y<0.0?(p.x<0.0?umbriel_corner_radius.x:umbriel_corner_radius.y)
        :(p.x<0.0?umbriel_corner_radius.w:umbriel_corner_radius.z);
    r=clamp(r,0.0,min(halfSize.x,halfSize.y));
    vec2 q=abs(p)-halfSize+r;
    return length(max(q,0.0))+min(max(q.x,q.y),0.0)-r;
}
vec4 window(vec2 uv) {
    vec4 source=umbriel_sample(uv);
    vec2 point=uv*umbriel_size;
    float d=diya_distance(point);
    if(d>0.0 || d<=-REACH) return source;
    vec4 lamps=diya_material(point,umbriel_size,d);
    return vec4(source.rgb*(1.0-lamps.a)+lamps.rgb*source.a,source.a);
}
'''
(root / 'border/diya-lights/shader.glsl').write_text(border)
(root / 'window/diya-glow-overlay/shader.glsl').write_text(overlay)
print('Generated Diya border and companion from shared artwork.')
